            comp = []
            stack = [(r, c)]
            seen[r][c] = True
            reaches_open_edge = False
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                if y in (0, h - 1) or x in (0, w - 1):
                    # An edge-touching component is exterior unless each
                    # contact on the edge is pinched between outline cells.
                    if y in (0, h - 1):
                        if not (x > 0 and x + 1 < w and grid[y][x-1] == wall and grid[y][x+1] == wall):
