                    if c2 < w - 1 and any(grid[r][c2] != wall for r in range(r1, r2 + 1)):
                        continue
                    for r in range(r1 + 1, r2):
                        for c in range(c1 + 1, c2):
                            if grid[r][c] == bg:
                                out[r][c] = 4
    return out
